import './DataTable.css';

export type Row = Record<string, string | number>;

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const PLACEHOLDER_COUNT = 5;
const PLACEHOLDER_COLS = 3;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns = rows.length > 0 ? Object.keys(rows[0]) : Array.from({ length: PLACEHOLDER_COLS }, (_, i) => `col${i}`);

  return (
    <table role="table" className="data-table">
      <thead>
        <tr>
          {columns.map((col) => (
            <th key={col} scope="col">{loading ? '\u00A0' : col}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {loading
          ? Array.from({ length: PLACEHOLDER_COUNT }, (_, rowIdx) => (
              <tr key={rowIdx}>
                {columns.map((col) => (
                  <td key={col}>
                    <span className="shimmer-cell">{'\u00A0'}</span>
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row, rowIdx) => (
              <tr key={rowIdx}>
                {columns.map((col) => (
                  <td key={col}>{row[col]}</td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}
